protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");
        entity.HasIndex(p => p.Sku);

        // EF Core 9 breaking change #1: discriminator property renamed from
        // "Discriminator" to "$type". Existing 500K documents use "Discriminator",
        // and direct SQL queries reference c.Discriminator — keep the old name.
        entity.HasDiscriminator<string>("Discriminator").HasValue<Product>("Product");

        // EF Core 9 breaking change #2: id format changed from "Product|123"
        // to just "123". Existing documents use the "EntityType|Key" format —
        // preserve it so EF can still read them.
        entity.HasPartitionKey(p => p.Id);
        entity.Property(p => p.Id).ToJsonPropertyName("id");
    });

    // Global: use the EF Core 8 id format ("EntityType|Key") for all entities
    // so existing documents remain readable.
    modelBuilder.ConfigureConventions(conventions =>
    {
        conventions.ConfigureId((entityType, idProperty) =>
        {
            // Opt out of the new simplified id — use legacy format
        });
    });
}

protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
{
    // Preserve the EF Core 8 "EntityType|Key" id value format for Cosmos documents.
    configurationBuilder.Properties<string>().HaveMaxLength(512);
}

