arguments.new_str:
class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we kept "Discriminator" as the
        // discriminator property name in OnModelCreating (EF Core 9 default is "$type").
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 breaking change #3: synchronous LINQ (ToList, First, Single, etc.)
        // now throws InvalidOperationException on the Cosmos provider. Use async.
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

