using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change #1 — Discriminator property renamed.
            // Default changed from "Discriminator" to "$type".
            // Existing 500K documents and direct SQL queries use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator")
                .HasValue<Product>("Product");

            // EF Core 9 breaking change #2 — id value format changed.
            // EF Core 8 stored a shadow "__id" property as JSON "id" with the
            // value "Product|123". EF Core 9 maps the CLR key directly to "id"
            // (just "123"). Restore the shadow property with the legacy format
            // so existing documents are still readable.
            entity.Property<string>("__id")
                .ToJsonPropertyName("id")
                .HasValueGenerator<LegacyCosmosIdGenerator>();
        });
    }
}

/// <summary>
/// Reproduces the EF Core 8 Cosmos id format: "EntityTypeName|KeyValue".
/// </summary>
class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;

    protected override string GenerateValue(EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var pk = entry.Property("Id").CurrentValue;
        return $"{entityType}|{pk}";
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

