using Microsoft.EntityFrameworkCore;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change #1 — Discriminator property renamed.
            // Default changed from "Discriminator" to "$type".
            // Existing 500K documents and direct SQL queries use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator")
                .HasValue<Product>("Product");

            // EF Core 9 breaking change #2 — id value format changed.
            // EF Core 8 generated id as "Product|123" (discriminator + key).
            // EF Core 9 defaults to just the key value ("123").
            // Restore the discriminator prefix so existing documents are readable.
            entity.HasDiscriminatorInJsonId();
        });
    }
}

class Product
{
    public int Id { get; set; }
    public string Sku { get; set; }
}

